{
  "id": "delta-payments-collect-writes-table-row",
  "function": "payments-collect",
  "kind": "happy",
  "source": ["GAP-5"],
  "expected_from": "decision:GAP-5",
  "spec_refs": [
    "blueprint:metadata.spec_resolutions[SI-6]",
    "blueprint:metadata.spec_resolutions[SI-7]",
    "blueprint:lambda_functions[payments-collect].notes",
    "blueprint:dynamodb_tables[PaymentTable]"
  ],
  "title": "收款必须落进 PaymentTable（进程内字典已作废，裁判只看响应看不到这张表）",
  "request": {
    "method": "POST",
    "path": "/payments/collect",
    "query": {},
    "headers": {},
    "body": {"chargeId": "ch-d1-collect"},
    "identity": null
  },
  "fixtures": {"PaymentTable": []},
  "expect": {
    "status": 200,
    "headers": {
      "contains": {
        "Access-Control-Allow-Origin": "*",
        "Content-Type": "application/json"
      }
    },
    "body": {
      "subset": {
        "receiptUrl": "https://payment.example.com/receipts/ch-d1-collect",
        "price": 150
      }
    },
    "tables_after": {
      "PaymentTable": {
        "count": 1,
        "contains": [
          {
            "chargeId": "ch-d1-collect",
            "receiptUrl": "https://payment.example.com/receipts/ch-d1-collect",
            "price": 150,
            "status": "captured",
            "mode": "simulation"
          }
        ]
      }
    }
  },
  "note": "GAP-5/SI-6：收款状态从 PaymentService._payments 迁到 PaymentTable，且必须跨实例可见。裁判用例（collect-then-read-payment）只比较 HTTP 响应，证明不了这笔记录真的在表里；本用例按 blueprint 的条目形状 {chargeId, receiptUrl, price, status, mode} 断言表状态。"
}

{
  "id": "delta-payments-collect-duplicate-overwrites",
  "function": "payments-collect",
  "kind": "boundary",
  "source": ["GAP-5", "GAP-17"],
  "expected_from": "decision:GAP-5",
  "spec_refs": [
    "blueprint:metadata.spec_resolutions[SI-17]",
    "blueprint:lambda_functions[payments-collect].notes",
    "POST /payments/collect#business_rules[7]"
  ],
  "title": "同一 chargeId 重复收款：不去重、整条覆盖，表里仍只有这一行",
  "request": {
    "method": "POST",
    "path": "/payments/collect",
    "query": {},
    "headers": {},
    "body": {"chargeId": "ch-d1-collect"},
    "identity": null,
    "repeat": 2
  },
  "fixtures": {"PaymentTable": []},
  "expect": {
    "status": 200,
    "body": {
      "subset": {
        "receiptUrl": "https://payment.example.com/receipts/ch-d1-collect",
        "price": 150
      }
    },
    "tables_after": {
      "PaymentTable": {
        "count": 1,
        "contains": [
          {"chargeId": "ch-d1-collect", "status": "captured", "price": 150}
        ]
      }
    }
  },
  "note": "SI-17：目标不得新增幂等/去重机制；PutItem 按主键 chargeId 覆盖，重复收款后表里恰好一行。与『去重丢弃第二次』的结果（同样一行）之外，本用例同时钉住『响应两次都是 200』——repeat=2 要求两次结果完全一致。"
}

{
  "id": "delta-payments-refund-marks-existing-row",
  "function": "payments-refund",
  "kind": "happy",
  "source": ["GAP-5"],
  "expected_from": "decision:GAP-5",
  "spec_refs": [
    "blueprint:metadata.spec_resolutions[SI-6]",
    "blueprint:lambda_functions[payments-refund].notes",
    "blueprint:dynamodb_tables[PaymentTable]"
  ],
  "title": "退款必须把 PaymentTable 里已存在那条的 status 改成 refunded（跨实例可见的状态迁移）",
  "request": {
    "method": "POST",
    "path": "/payments/refund",
    "query": {},
    "headers": {},
    "body": {"chargeId": "ch-d1-a"},
    "identity": null
  },
  "fixtures": {
    "PaymentTable": [
      {
        "chargeId": "ch-d1-a",
        "receiptUrl": "https://payment.example.com/receipts/ch-d1-a",
        "price": 150,
        "status": "captured",
        "mode": "simulation"
      }
    ]
  },
  "expect": {
    "status": 200,
    "headers": {
      "contains": {
        "Access-Control-Allow-Origin": "*",
        "Content-Type": "application/json"
      }
    },
    "body": {"has_fields": ["refundId"]},
    "tables_after": {
      "PaymentTable": {
        "count": 1,
        "contains": [{"chargeId": "ch-d1-a", "status": "refunded"}]
      }
    }
  },
  "note": "GAP-5/SI-6：refund 用条件 UpdateItem 改表里那条的 status（refundId 是新生成的随机串，只断言存在）。裁判只比较响应体，看不到目标表里这次状态迁移；『退款后 status=refunded 可被 GET 读回』那一半由裁判 refund-then-read-payment 负责，本用例负责表侧。"
}

{
  "id": "delta-payments-refund-never-collected-creates-no-row",
  "function": "payments-refund",
  "kind": "boundary",
  "source": ["GAP-5"],
  "expected_from": "decision:GAP-5",
  "spec_refs": [
    "blueprint:metadata.spec_resolutions[SI-6]",
    "blueprint:lambda_functions[payments-refund].notes",
    "blueprint:dynamodb_tables[PaymentTable]"
  ],
  "title": "退款一笔从未收款的 chargeId：仍 200，但绝不新建条目、不碰已有条目",
  "request": {
    "method": "POST",
    "path": "/payments/refund",
    "query": {},
    "headers": {},
    "body": {"chargeId": "ch-d1-ghost"},
    "identity": null
  },
  "fixtures": {
    "PaymentTable": [
      {
        "chargeId": "ch-d1-a",
        "receiptUrl": "https://payment.example.com/receipts/ch-d1-a",
        "price": 150,
        "status": "captured",
        "mode": "simulation"
      }
    ]
  },
  "expect": {
    "status": 200,
    "body": {"has_fields": ["refundId"]},
    "tables_after": {
      "PaymentTable": {
        "count": 1,
        "contains": [{"chargeId": "ch-d1-a", "status": "captured"}],
        "not_contains": [{"chargeId": "ch-d1-ghost"}]
      }
    }
  },
  "note": "blueprint payments-refund / PaymentTable notes：条件 UpdateItem（attribute_exists(chargeId)）条件失败=从未收款→什么都不做、绝不新建条目。单体这一臂无表可看（内存字典），裁判比较的是响应（恒 200，SI-6(d)）；『不新建、不改别的行』是目标独有的表侧契约。_refunds 不持久化（SI-6）——表里不得出现任何 refund 记录行。"
}

{
  "id": "delta-bookings-create-anon-401-gateway",
  "function": "bookings-create",
  "kind": "error",
  "source": ["GAP-10", "GAP-13"],
  "expected_from": "ruling:R-A1-a2-1",
  "spec_refs": [
    "blueprint:metadata.spec_resolutions[SI-9]",
    "blueprint:metadata.spec_resolutions[SI-10]",
    "POST /bookings#responses[0]"
  ],
  "title": "匿名 POST /bookings：网关授权器直接 401，报文是 {message} 形状，请求不进函数、零表访问",
  "request": {
    "method": "POST",
    "path": "/bookings",
    "query": {},
    "headers": {},
    "body": {"outboundFlightId": "fl-d1-1", "chargeId": "ch-d1-saga", "customerId": "user-victim-d1"},
    "identity": null
  },
  "fixtures": {
    "FlightTable": [
      {"id": "fl-d1-1", "departureAirportCode": "SFO", "arrivalAirportCode": "LAX", "departureDate": "2026-12-01", "seatCapacity": 5, "maximumSeating": 10}
    ],
    "BookingTable": []
  },
  "expect": {
    "status": 401,
    "body": {"has_fields": ["message"]},
    "tables_after": {
      "FlightTable": {"count": 1, "contains": [{"id": "fl-d1-1", "seatCapacity": 5}]},
      "BookingTable": {"count": 0},
      "PaymentTable": {"count": 0},
      "LoyaltyTable": {"count": 0}
    },
    "sdk_calls": {
      "excludes": [
        {"table": "BookingTable"},
        {"table": "FlightTable"},
        {"table": "PaymentTable"},
        {"table": "LoyaltyTable"},
        {"table": "UserGroupsTable"}
      ]
    }
  },
  "note": "R-A1-a2-1/SI-9：单体的三态 401（缺头/格式错/令牌无效，body {error}）在目标上收敛为『授权器 401』一种，body 是 HTTP API 默认 {message} 形状；『不消耗任何 DynamoDB 读写』这一半契约保持。裁判在 P 层按裁定放过这一步的实际报文，本用例按裁定正向钉住新形状。网关自答 401 的 ACAO 头由 CorsConfiguration 负责（SI-14），其有无属模板核对（S3c/C7b），不在这里断言运行态模拟的网关头。"
}

